const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const region = ee.Geometry.Polygon(
      [[[-10, 64], [10, 64], [10, 72], [-10, 72], [-10, 64]]], null, false
    );
    const targetStart = '2019-06-05';
    const targetEnd = '2019-06-06';
    const widenStart = '2019-06-04';
    const widenEnd = '2019-06-07';
    const scale = 4000;
    const chlBand = 'chlor_a';
    const bloomThresh = 2.0; // mg/m^3
    const minBloomPct = 5.0; // %

    async function attempt(dataset, start, end) {
      let col = ee.ImageCollection(dataset)
        .filterDate(start, end)
        .filterBounds(region)
        .select([chlBand]);
      const size = await col.size().getInfo();
      if (size === 0) return { size: 0, image: null, dataset, start, end };
      const img = col.median().clip(region);
      return { size, image: img, dataset, start, end };
    }

    // 2. Data Acquisition & Check with fallback strategy
    let result = await attempt('NASA/OCEANDATA/MODIS-Aqua/L3SMI', targetStart, targetEnd);
    if (result.size === 0) result = await attempt('NASA/OCEANDATA/MODIS-Terra/L3SMI', targetStart, targetEnd);
    if (result.size === 0) result = await attempt('NASA/OCEANDATA/MODIS-Aqua/L3SMI', widenStart, widenEnd);
    if (result.size === 0) result = await attempt('NASA/OCEANDATA/MODIS-Terra/L3SMI', widenStart, widenEnd);

    if (result.size === 0 || !result.image) {
      console.log(`Images: 0 (all attempts)`);
      console.log('C1');
      return;
    }

    console.log(`Dataset: ${result.dataset}`);
    console.log(`Date window: ${result.start} to ${result.end}, Images: ${result.size}`);

    const img = result.image;

    // 3. Processing & Valid Pixel Counts
    const totalCountDict = await ee.Image(1).rename('ones').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();
    const totalCount = totalCountDict ? totalCountDict.ones : null;

    const validCountDict = await img.select(chlBand).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();
    const validCount = validCountDict ? validCountDict[chlBand] : 0;

    if (!Number.isFinite(validCount) || validCount === 0) {
      console.log(`Valid pixels: 0 of ${totalCount || 'NA'}`);
      console.log('C2');
      return;
    }

    const bloomCountDict = await img.select(chlBand).gt(bloomThresh).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();
    const bloomCount = bloomCountDict ? bloomCountDict[chlBand] : 0;

    const pctDict = await img.select(chlBand).reduceRegion({
      reducer: ee.Reducer.percentile([50, 90]),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();
    const p50 = pctDict ? pctDict[`${chlBand}_p50`] : null;
    const p90 = pctDict ? pctDict[`${chlBand}_p90`] : null;

    const coveragePct = totalCount && Number.isFinite(totalCount) ? (100.0 * validCount / totalCount) : null;
    const bloomPct = (100.0 * (bloomCount || 0) / validCount);

    // 4. Validation & Final Answer
    const invalid =
      p50 === null || p90 === null ||
      !Number.isFinite(p50) || !Number.isFinite(p90) ||
      p50 < 0 || p90 < 0 || p90 > 1000;

    console.log(`Valid pixels: ${validCount} of ${totalCount || 'NA'} (cov: ${coveragePct !== null ? coveragePct.toFixed(1) : 'NA'}%)`);
    console.log(`Chl-a median: ${Number.isFinite(p50) ? p50.toFixed(2) : 'NA'} mg/m^3`);
    console.log(`Chl-a p90: ${Number.isFinite(p90) ? p90.toFixed(2) : 'NA'} mg/m^3`);
    console.log(`Bloom >${bloomThresh} mg/m^3: ${bloomCount} px (${bloomPct.toFixed(1)}%)`);

    if (invalid) {
      console.log('C3');
      return;
    }

    const hasBloom = (bloomPct >= minBloomPct) || (p90 >= bloomThresh);
    console.log(hasBloom ? 'A' : 'B');
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
